#include <iostream>

#include <noarr/traversers.hpp>

// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "lu.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();
constexpr auto k_vec = noarr::vector<'k'>();
constexpr auto t_vec = noarr::vector<'t'>();

struct tuning {
	// A: i x j, row-major: scalar<num_t> ^ vector<'j'> ^ vector<'i'>
	DEFINE_PROTO_STRUCT(a_layout, j_vec ^ i_vec);
} tuning;

// 1D helper structures for k- and t-iterations (no actual data, only for traversal)
constexpr auto k_structure = noarr::scalar<char>() ^ k_vec;
constexpr auto t_structure = noarr::scalar<char>() ^ t_vec;

// Tiling proto-structure used in the upper (U) update of LU:
// - split the contiguous 'j' dimension into blocks 'J' (block index) and 'j' (index inside block)
// - use into_blocks_dynamic so we correctly handle a last partial block
// - hoist 'J' so whole tiles are processed together (good cache behavior)
constexpr auto upper_j_tiling =
	noarr::into_blocks_dynamic<'j', 'J', 'j', 'u'>(noarr::lit<32>) ^ // tile size = 32 columns
	noarr::hoist<'J'>();

// initialization function
void init_array(auto A) {
	// A: i x j
	using namespace noarr;

	auto n = A | get_length<'i'>(); // matrix is n x n

	// ------------------------------------------------------------------
	// Phase 1: Initialize A as unit-lower plus some values below diagonal
	//          and zeros above.
	// ------------------------------------------------------------------
	traverser(A).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);

		const int nn = static_cast<int>(n);
		const int jj = static_cast<int>(j);

		if (j < i) {
			// Original Polybench-style initialization:
			//   val = (DATA_TYPE)((-j % n)); val /= n; val += 1;
			// Note: for 0 <= j < n, (-j % n) == -j in C++,
			// so this is equivalent to 1 - j/n.
			num_t val = static_cast<num_t>((-jj % nn));
			val /= static_cast<num_t>(nn);
			val += static_cast<num_t>(1);
			A[state] = val;
		} else if (j == i) {
			A[state] = static_cast<num_t>(1);
		} else { // j > i
			A[state] = static_cast<num_t>(0);
		}
	});

	// ------------------------------------------------------------------
	// Phase 2: Make the matrix positive semi-definite:
	//          B[r][s] = sum_t A[r][t] * A[s][t]; then A = B.
	//
	// Compared to the original implementation (outer loop over t,
	// inner over r,s), we compute one dot product per (r,s):
	//
	//   for each (r,s):
	//     B[r,s] = sum_t A[r,t] * A[s,t];
	//
	// For each pair (r,s) the sequence of t values is still 0..n-1,
	// so the per-element reduction order is identical (same floating-
	// point rounding), but locality inside the t-loop is improved
	// and the compiler gets a clear reduction pattern.
	// ------------------------------------------------------------------
	auto B = noarr::bag(A.structure());

	traverser(B).for_each([&](auto rs_state) {
		auto [r, s] = get_indices<'i', 'j'>(rs_state);

		num_t sum = static_cast<num_t>(0);

		traverser(t_structure)
			.order(noarr::set_length<'t'>(n))
			.for_each([&](auto t_state) {
				auto t = get_index<'t'>(t_state);

				auto rt_state = noarr::idx<'i', 'j'>(r, t);
				auto st_state = noarr::idx<'i', 'j'>(s, t);

				sum += A[rt_state] * A[st_state];
			});

		B[rs_state] = sum;
	});

	// Copy B back into A
	traverser(A, B).for_each([&](auto state) {
		A[state] = B[state];
	});
}

// computation kernel
[[gnu::flatten, gnu::noinline]]
void kernel_lu(auto A) {
	// A: i x j (n x n)
	using namespace noarr;

	auto n = A | get_length<'i'>();

	#pragma scop
	traverser(A).template for_dims<'i'>([&](auto trav_i) {
		// trav_i represents a single row i (dimension 'i' fixed)
		auto state_i = trav_i.state();
		auto i_idx = get_index<'i'>(state_i);

		// ------------------------------------------------------
		// 1) Lower-triangular update: compute L(i,j) for j < i
		//
		//    Original code (for each j < i):
		//      for k = 0..j-1:
		//        A[i,j] -= A[i,k] * A[k,j];
		//      A[i,j] /= A[j,j];
		//
		//    Here we rewrite the inner k-loop as a local reduction:
		//      sum = sum_{k=0..j-1} A[i,k] * A[k,j];
		//      A[i,j] = (A[i,j] - sum) / A[j,j];
		//
		//    This keeps the k-order identical for each (i,j) and
		//    exposes a clear reduction, which helps vectorization.
		// ------------------------------------------------------
		if (i_idx > 0) {
			// Restrict traversal to columns j in [0, i_idx) for this row
			auto trav_j_lt_i = trav_i.order(noarr::slice<'j'>(0, i_idx));

			trav_j_lt_i.template for_dims<'j'>([&](auto trav_ij) {
				auto state_ij = trav_ij.state();
				auto j_idx = get_index<'j'>(state_ij);

				// Compute sum_{k=0}^{j-1} A[i,k] * A[k,j]
				num_t sum = static_cast<num_t>(0);

				if (j_idx > 0) {
					traverser(k_structure)
						.order(noarr::set_length<'k'>(j_idx))
						.for_each([&](auto k_state) {
							auto k_idx = get_index<'k'>(k_state);

							auto ik_state = noarr::idx<'i', 'j'>(i_idx, k_idx);
							auto kj_state = noarr::idx<'i', 'j'>(k_idx, j_idx);

							sum += A[ik_state] * A[kj_state];
						});
				}

				// Update A[i,j] using the accumulated sum, then divide by A[j,j].
				// Using the state from trav_ij (which already fixes both i and j)
				// avoids rebuilding an index state.
				num_t &Aij = A[state_ij];
				Aij -= sum;

				auto jj_state = noarr::idx<'i', 'j'>(j_idx, j_idx);
				Aij /= A[jj_state];
			});
		}

		// ------------------------------------------------------
		// 2) Upper-triangular (and diagonal) update: compute U(i,j)
		//    for j in [i, n).
		//
		//    Original structure (for fixed i):
		//      for j in [i, n):
		//        for k in [0, i):
		//          A[i,j] -= A[i,k] * A[k,j];
		//
		//    We legally interchange the j and k loops:
		//      for k in [0, i):
		//        for j in [i, n):
		//          A[i,j] -= A[i,k] * A[k,j];
		//
		//    For each (i,j) the sequence of k-values remains 0..i-1,
		//    so floating-point results are bitwise identical. This
		//    form:
		//      - reuses A[i,k] across all j for fixed (i,k)
		//      - walks A[k, j] and A[i, j] contiguously in j
		//      - allows us to tile the j-dimension for better cache
		//        behavior via upper_j_tiling.
		// ------------------------------------------------------
		auto len_second = n - i_idx;

		// For i == 0 the sum over k is empty, so A[0, j] stays unchanged.
		// We can skip the whole upper update for i == 0.
		if (len_second > 0 && i_idx > 0) {
			// Traverser restricted to columns j in [i_idx, n) for the current row
			auto trav_j_ge_i = trav_i.order(noarr::slice<'j'>(i_idx, len_second));

			// Outer loop over k in [0, i)
			traverser(k_structure)
				.order(noarr::set_length<'k'>(i_idx))
				.for_each([&](auto k_state) {
					auto k_idx = get_index<'k'>(k_state);

					// A[i,k] is reused for all j in this row and this k
					auto ik_state = noarr::idx<'i', 'j'>(i_idx, k_idx);
					const num_t aik = A[ik_state];

					// Apply blocked traversal over the j-dimension to improve
					// cache locality for A[i, j] and A[k, j].
					auto trav_j_blocks = trav_j_ge_i.order(upper_j_tiling);

					trav_j_blocks.template for_dims<'J'>([&](auto trav_block) {
						// Inside a block, iterate all valid j (and any internal
						// helper dimensions from into_blocks_dynamic are handled
						// by the traverser; the state we see only has 'i' and 'j').
						trav_block.for_each([&](auto state_ij) {
							auto j_idx = get_index<'j'>(state_ij);

							auto kj_state = noarr::idx<'i', 'j'>(k_idx, j_idx);
							A[state_ij] -= aik * A[kj_state];
						});
					});
				});
		}
	});
	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;

	auto set_lengths =
		noarr::set_length<'i'>(n) ^
		noarr::set_length<'j'>(n);

	// A: n x n
	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths);

	// initialize data
	init_array(A.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_lu(A.get_ref());

	auto end = std::chrono::high_resolution_clock::now();

	auto duration = std::chrono::duration<long double>(end - start);

	// print results (and prevent dead-code elimination)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, A.get_ref() ^ noarr::hoist<'i'>());
	}

	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;

	return 0;
}
