		auto state_i = trav_i.state();
		std::size_t i_idx = get_index<'i'>(state_i);

		// ------------------------------------------------------------------
		// 1) Lower-triangular update: j in [0, i)
		//    A[i,j] = (A[i,j] - sum_{k<j} A[i,k]*A[k,j]) / A[j,j]
		// ------------------------------------------------------------------
