			// Restrict current row i to columns j < i
			auto trav_j_lt_i = trav_i.order(noarr::slice<'j'>(0, i_idx));

			// j is the only remaining dimension; it is traversed in increasing
			// order, matching the original loop j = 0..i-1.
			trav_j_lt_i.template for_dims<'j'>([&](auto trav_ij) {
				auto ij_state = trav_ij.state();
				std::size_t j_idx = get_index<'j'>(ij_state);

				// Work on a local accumulator for A[i,j]; this preserves the
				// original operation order (sequential subtracts in k) but
				// keeps the value in registers instead of memory.
				num_t a_ij = A[ij_state];

				// For j == 0, the reduction is empty and we only divide by
				// A[0,0], exactly as in the original code.
				if (j_idx > 0) {
					// k-loop: k in [0, j)
					traverser(k_structure)
						.order(noarr::set_length<'k'>(j_idx))
						.for_each([&](auto k_state) {
							std::size_t k_idx = get_index<'k'>(k_state);

							auto ik_state = noarr::idx<'i', 'j'>(i_idx, k_idx);
							auto kj_state = noarr::idx<'i', 'j'>(k_idx, j_idx);

							a_ij -= A[ik_state] * A[kj_state];
						});
				}

				// Final division by the pivot A[j,j]
				auto jj_state = noarr::idx<'i', 'j'>(j_idx, j_idx);
				A[ij_state] = a_ij / A[jj_state];
			});
		}

		// ------------------------------------------------------------------
		// 2) Upper-triangular (and diagonal) update: j in [i, n)
		//
		// Original structure (for fixed i):
		//   for j = i..n-1:
		//     for k = 0..i-1:
		//       A[i,j] -= A[i,k] * A[k,j];
		//
		// Here we legally interchange the loops to:
		//   for k = 0..i-1:
		//     for j = i..n-1:
		//       A[i,j] -= A[i,k] * A[k,j];
		//
		// For each fixed (i,j), the sequence of k values is still processed
		// in strictly increasing order, so the arithmetic on A[i,j] is
		// identical to the original code. The advantage is that we:
		//   - reuse A[i,k] across all j in the row,
		//   - walk A[k,j] and A[i,j] along contiguous j.
		// ------------------------------------------------------------------
